-- MLS foundation: schedules and attendance; no live stats or binary predictions.
alter table public.sports drop constraint sports_id_check;
alter table public.sports add constraint sports_id_check check (id in ('mlb','nfl','nba','mls'));

alter table public.games
  add column season_key text,
  add column season_label text,
  add column decision_method text,
  add column home_shootout_score integer,
  add column away_shootout_score integer;
alter table public.games add constraint games_mls_season_check
  check (sport_id <> 'mls' or (season_key is not null and season_label is not null));
alter table public.games add constraint games_decision_method_check
  check (decision_method is null or (sport_id = 'mls' and status = 'final' and decision_method in ('regulation','extra_time','shootout')));
alter table public.games add constraint games_shootout_check check (
  (home_shootout_score is null and away_shootout_score is null and decision_method is distinct from 'shootout')
  or (sport_id = 'mls' and status = 'final' and decision_method = 'shootout'
    and home_shootout_score is not null and away_shootout_score is not null
    and home_shootout_score >= 0 and away_shootout_score >= 0 and home_shootout_score <> away_shootout_score
    and home_score is not null and away_score is not null and home_score = away_score
    and not is_tie and winner_team_id is not null
    and winner_team_id = case when home_shootout_score > away_shootout_score then home_team_id else away_team_id end)
);
create index games_sport_season_key_idx on public.games(sport_id, season_key);
comment on column public.games.season_key is 'Stable competition season identity; 2027 transition mapping must be verified separately from 2027-28.';

